mapper.select:
select r.record_id, r.policy_id, r.target_id, r.match_time, r.status, r.fund_amount, r.audit_status, r.risk_level, r.proof_file,
       p.policy_name as policy_name,
       t.target_name as target_name,
       t.identifier as identifier,
       p.pdf_url as pdf_url,
       p.pdf_name as pdf_name
from ee_match_record r
left join ee_policy p on r.policy_id = p.policy_id
left join ee_target_data t on r.target_id = t.target_id

     and r.record_id = #{recordId}
     and r.policy_id = #{policyId}
     and r.target_id = #{targetId}
     and r.status = #{status}
     and r.audit_status = #{auditStatus}
     and r.risk_level = #{riskLevel}
     and p.policy_name like concat('%', #{policyName}, '%')
     and t.target_name like concat('%', #{targetName}, '%')

order by r.record_id desc

mapper.update:
update ee_match_record
update_time = #{updateTime}, policy_id = #{policyId}, target_id = #{targetId}, match_time = #{matchTime}, status = #{status}, fund_amount = #{fundAmount}, audit_status = #{auditStatus}, risk_level = #{riskLevel}, proof_file = #{proofFile},
where record_id = #{recordId}
